  specialCases: [
    {
      id: 'its-vs-its',
      title: 'Its va It\'s farqi',
      rule: "Its — possessive adjective (uning, jonsiz/hayvon uchun):\n  The dog wagged its tail. (It dumini likillatdi)\n  The company increased its profits. (Kompaniya o'z foydasini oshirdi)\n\nIt's — It is yoki It has qisqartmasi:\n  It's a beautiful day. (It is — bu chiroyli kun)\n  It's been a long time. (It has — uzoq vaqt bo'ldi)\n\n🔴 FARQ:\n  Its = uniki (egalik)\n  It's = It is / It has (qisqartma)\n\nApostrof 's' ikkala vazifani bajaradi — bu chalkashlikka sabab bo'ladi. Eslab qoling: Possessive adjectives hech qachon apostrof olmaydi! (my, your, his, her, its, our, their)",
      mnemonic: "Its = egalik (apostrof YO'Q). It's = qisqartma (apostrof BOR). QOIDA: Barcha possessive adjective larda apostrof yo'q: my, your, his, her, its, our, their. Agar apostrof ko'rsangiz → bu qisqartma!",
      commonMistakes: "❌ The cat licked it's paw. (It's = It is! Bunday ma'no kelib chiqadi: 'Mushuk u uning panjasini yaladi')\n✅ The cat licked its paw.\n\n❌ Its a beautiful day. (egalik kerak emas)\n✅ It's a beautiful day. (It is)",
      examples: [
        { en: 'The bird built its nest in the tree.', uz: "Qush uyasini daraxtga qurdi." },
        { en: 'It\'s raining outside.', uz: "Tashqarida yomg'ir yog'moqda." },
        { en: 'Every country has its own traditions.', uz: "Har bir mamlakatning o'z an'analari bor." },
      ],
      drills: [
        { id: 24138, type: 'fill-blank', instruction: "Its yoki It's bilan to'ldiring:", question: 'The cat is playing with ___ toy.', blanks: ['its'], explanation: "Mushukning o'yinchog'i → egalik → 'its'." },
        { id: 24139, type: 'fill-blank', instruction: "Its yoki It's:", question: '___ a very hot day today.', blanks: ["It's"], explanation: "It is = It's. Ob-havo haqida gap." },
        { id: 24140, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: 'I think ___ going to rain.', options: ['its', "it's", 'its\'', 'it is'], correct: "it's", explanation: "It is going to rain → 'It's' qisqartmasi." },
      ],
    },
    {
      id: 'double-possessive',
      title: "Double Possessive (a friend of mine)",
      rule: "Double possessive — ikki xil egalik birga ishlatiladi:\n\n📌 STRUCTURE: a/an/this/that + noun + of + possessive pronoun/mine/yours/his/hers/ours/theirs\n\n  A friend of mine = mening bir do'stim\n  A colleague of hers = uning bir hamkasbi\n  That car of his = uning o'sha mashinasi\n  This idea of yours = sening bu fikring\n\n📌 NIMA UCHUN KERAK?\n  'My friend' = ma'lum bir do'st. 'A friend of mine' = ko'p do'stlarimdan biri.\n\n  He is my friend. (U mening do'stim — yaqin do'st)\n  He is a friend of mine. (U mening bir do'stim — hamma do'stlarimdan biri)\n\n🔴 QOIDA: 'Of' dan keyin POSSESSIVE PRONOUN (mine/yours/his/hers/...) ishlatiladi, adjective (my/your/his/her/...) EMAS!\n  ✅ A friend of mine\n  ❌ A friend of my\n\n📌 Yana bir misol:\n  That dog of theirs is very noisy. (Ularning o'sha iti juda shovqinli)\n  This painting of yours is beautiful. (Sening bu rasming chiroyli)\n  She is a neighbour of ours. (U bizning bir qo'shnimiz)",
      mnemonic: "A friend of mine = ko'p do'stlarimdan biri. 'Of' dan keyin DOIM mine/yours/his/hers/ours/theirs (pronoun). 'A friend of my' — XATO! OF + PRONOUN.",
      commonMistakes: "❌ She is a friend of my. (Of dan keyin 'my' -> XATO! 'mine' kerak)\n✅ She is a friend of mine.\n\n❌ That is a car of him. (him emas, 'his' kerak)\n✅ That is a car of his.\n\n🔴 ESLATMA: 'Of mine' va 'my' bir xil ma'noda emas!\n  My friend = mening (aniq) do'stim\n  A friend of mine = mening do'stlarimdan biri",
      examples: [
        { en: 'She is a friend of mine from university.', uz: 'U mening universitetdan bir do\'stim.' },
        { en: 'That car of his is very expensive.', uz: 'Uning o\'sha mashinasi juda qimmat.' },
        { en: 'A colleague of hers works in London.', uz: 'Uning bir hamkasbi Londonda ishlaydi.' },
      ],
      drills: [
        { id: 24141, type: 'fill-blank', instruction: "Double possessive bilan to'ldiring:", question: 'She is a friend of ___.', blanks: ['mine'], explanation: "Of + mine — 'Of' dan keyin possessive pronoun." },
        { id: 24142, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "It's a painting of ___.", options: ['her', 'hers', 'she', 'herself'], correct: 'hers', explanation: "Of + hers (possessive pronoun)." },
        { id: 24143, type: 'error-correction', instruction: 'Xatoni toping va to\'g\'irlang:', question: 'He is a friend of my brother.', errorPart: 'my brother', correct: 'He is a friend of my brother\'s.', explanation: "Double possessive — 'a friend of my brother's'. Ikkala egalik birga." },
      ],
    },
  ],
