  tests: [
    { id: 24215, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Some qanday gaplarda ishlatiladi?", blanks: ["ijobiy va takliflarda"], explanation: "Some — ijobiy gaplar va taklif/iltimos savollarida." },
    { id: 24216, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Any qanday gaplarda ishlatiladi?", blanks: ["inkor va savollarda"], explanation: "Any — inkor va savollarda. Ijobiy gaplarda 'har qanday' ma'nosida." },
    { id: 24217, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "No qanday ma'noni bildiradi?", blanks: ["hech qanday ... yo'q"], explanation: "No = not any = hech qanday ... yo'q." },
    { id: 24218, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Every + ___ ot?", blanks: ["birlik"], explanation: "Every + birlik ot + birlik fe'l." },
    { id: 24219, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Would you like some tea? — Nima uchun 'some'?", blanks: ["taklif uchun"], explanation: "Taklif (offer) → 'some', hatto savol bo'lsa ham." },
    { id: 24220, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "I have ___ money. (I am rich!)", blanks: ["some"], explanation: "Ijobiy gap → 'some'." },
    { id: 24221, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "I don't have ___ money.", blanks: ["any"], explanation: 'Inkor → \'any\'.: bu qoidada \'any\'. ishlatiladi' },
    { id: 24222, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "___ knows the answer.", blanks: ["Everybody"], explanation: "'Everybody' + birlik fe'l 'knows'." },
    { id: 24223, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "There is ___ in the room. It is empty.", blanks: ["nobody"], explanation: "Xona bo'sh → hech kim yo'q → 'nobody'." },
    { id: 24224, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Can I have ___ water, please?", blanks: ["some"], explanation: "Iltimos (request) → 'some'." },
    { id: 24225, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Which sentence has a double negative?", options: ["I don't know nothing.", "I  know nothing.", "know don't I nothing.", "nothing. don't know I"], correct: "I don't know nothing.", explanation: "Double negative: 'don't know nothing' = 'I know nothing' degan ma'noda, lekin grammatik jihatdan xato. Ingliz tilida ikki karra inkor to'g'ri emas." },
    { id: 24226, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "You can choose ___ book — it doesn't matter.", blanks: ["any"], explanation: "'Any' = har qanday (it doesn't matter which). Ijobiy gap." },
    { id: 24227, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Which is CORRECT?", options: ["All children are happy.", "All children is happy.", "All child are happy.", "All children happy."], correct: "All children are happy.", explanation: "'All' + ko'plik ot + ko'plik fe'l: 'All children are happy.'" },
    { id: 24228, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Nobody ___ the answer.", blanks: ["knows"], explanation: "Nobody + ijobiy fe'l (not kerak emas). 'Nobody knows'." },
    { id: 24229, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Which sentence means the SAME as 'I have no friends'?", blanks: ["I don't have any friends."], explanation: "'No' = 'not any'. 'I have no friends' = 'I don't have any friends'." },
  ],
